```python
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_CPP = r"""
void run_attn_v4(long q, long k, long v, long o,
                 int bs, int lq, int lk, int dim, int dtype);
"""

_CUDA = r'''
#include <cuda_runtime.h>
#include <cuda_bf16.h>
#include <cuda_fp16.h>
#include <cublasLt.h>
#include <stdint.h>
#include <float.h>
#include <math.h>

template<typename T> __device__ __forceinline__ float to_f(T x);
template<> __device__ __forceinline__ float to_f<float>(float x){ return x; }
template<> __device__ __forceinline__ float to_f<half>(half x){ return __half2float(x); }
template<> __device__ __forceinline__ float to_f<nv_bfloat16>(nv_bfloat16 x){ return __bfloat162float(x); }

template<typename T> __device__ __forceinline__ T from_f(float x);
template<> __device__ __forceinline__ float from_f<float>(float x){ return x; }
template<> __device__ __forceinline__ half from_f<half>(float x){ return __float2half_rn(x); }
template<> __device__ __forceinline__ nv_bfloat16 from_f<nv_bfloat16>(float x){ return __float2bfloat16_rn(x); }

template<typename T>
__global__ void softmax_v_kernel(const float* __restrict__ S,
                                 const T* __restrict__ V,
                                 T* __restrict__ O,
                                 int bs, int lq, int lk, int dim) {
    int row = blockIdx.x;
    int b = row / lq;
    int q = row - b * lq;
    int tid = threadIdx.x;
    int od = tid;

    const float* sp = S + (int64_t)row * lk;
    const T* vb = V + (int64_t)b * lk * dim;
    T* op = O + ((int64_t)b * lq + q) * dim;

    float m = -FLT_MAX;
    for (int j = 0; j < lk; ++j) {
        m = fmaxf(m, sp[j]);
    }

    float den = 0.f;
    float acc = 0.f;
    bool has = od < dim;

    for (int j = 0; j < lk; ++j) {
        float e = __expf(sp[j] - m);
        den += e;
        if (has) acc += e * to_f<T>(vb[(int64_t)j * dim + od]);
    }

    if (has) op[od] = from_f<T>(acc / den);
}

static cublasLtHandle_t get_lt() {
    static cublasLtHandle_t h = nullptr;
    if (!h) cublasLtCreate(&h);
    return h;
}

void matmul_scores(cublasLtHandle_t lt,
                   const void* Q, const void* K, float* S,
                   int bs, int lq, int lk, int dim,
                   cudaDataType_t type) {
    cublasLtMatmulDesc_t op;
    cublasLtMatrixLayout_t Ad, Bd, Cd;

    cublasOperation_t transa = CUBLAS_OP_N;
    cublasOperation_t transb = CUBLAS_OP_T;

    cublasLtMatmulDescCreate(&op, CUBLAS_COMPUTE_32F, CUDA_R_32F);
    cublasLtMatmulDescSetAttribute(op, CUBLASLT_MATMUL_DESC_TRANSA, &transa, sizeof(transa));
    cublasLtMatmulDescSetAttribute(op, CUBLASLT_MATMUL_DESC_TRANSB, &transb, sizeof(transb));

    cublasLtOrder_t order = CUBLASLT_ORDER_ROW;

    cublasLtMatrixLayoutCreate(&Ad, type, lq, dim, dim);
    cublasLtMatrixLayoutSetAttribute(Ad, CUBLASLT_MATRIX_LAYOUT_ORDER, &order, sizeof(order));

    cublasLtMatrixLayoutCreate(&Bd, type, lk, dim, dim);
    cublasLtMatrixLayoutSetAttribute(Bd, CUBLASLT_MATRIX_LAYOUT_ORDER, &order, sizeof(order));

    cublasLtMatrixLayoutCreate(&Cd, CUDA_R_32F, lq, lk, lk);
    cublasLtMatrixLayoutSetAttribute(Cd, CUBLASLT_MATRIX_LAYOUT_ORDER, &order, sizeof(order));

    float alpha = rsqrtf((float)dim);
    float beta = 0.f;

    cublasLtMatmulPreference_t pref;
    cublasLtMatmulPreferenceCreate(&pref);

    size_t wsSize = 1 << 20;
    void* ws = nullptr;
    cudaMalloc(&ws, wsSize);
    cublasLtMatmulPreferenceSetAttribute(
        pref, CUBLASLT_MATMUL_PREF_MAX_WORKSPACE_BYTES, &wsSize, sizeof(wsSize));

    cublasLtMatmulHeuristicResult_t heur;
    int ret = 0;
    cublasLtMatmulAlgoGetHeuristic(lt, op, Ad, Bd, Cd, Cd, pref, 1, &heur, &ret);

    size_t esz = (type == CUDA_R_32F ? 4 : 2);

    for (int b = 0; b < bs; ++b) {
        const char* Ap = (const char*)Q + (int64_t)b * lq * dim * esz;
        const char* Bp = (const char*)K + (int64_t)b * lk * dim * esz;
        float* Cp = S + (int64_t)b * lq * lk;

        cublasLtMatmul(
            lt, op,
            &alpha, Ap, Ad, Bp, Bd,
            &beta, Cp, Cd, Cp, Cd,
            ret ? &heur.algo : nullptr,
            ws, wsSize, 0);
    }

    cudaFree(ws);
    cublasLtMatmulPreferenceDestroy(pref);
    cublasLtMatrixLayoutDestroy(Ad);
    cublasLtMatrixLayoutDestroy(Bd);
    cublasLtMatrixLayoutDestroy(Cd);
    cublasLtMatmulDescDestroy(op);
}

void run_attn_v4(long q, long k, long v, long o,
                 int bs, int lq, int lk, int dim, int dtype) {
    float* S = nullptr;
    cudaMalloc(&S, (size_t)bs * lq * lk * sizeof(float));

    cudaDataType_t type =
        dtype == 1 ? CUDA_R_32F : (dtype == 2 ? CUDA_R_16F : CUDA_R_16BF);

    matmul_scores(get_lt(), (const void*)q, (const void*)k, S,
                  bs, lq, lk, dim, type);

    int th = 1;
    while (th < dim) th <<= 1;
    if (th < 32) th = 32;
    if (th > 1024) th = 1024;

    if (dtype == 1) {
        softmax_v_kernel<float><<<bs * lq, th>>>(
            S, (const float*)v, (float*)o, bs, lq, lk, dim);
    } else if (dtype == 2) {
        softmax_v_kernel<half><<<bs * lq, th>>>(
            S, (const half*)v, (half*)o, bs, lq, lk, dim);
    } else {
        softmax_v_kernel<nv_bfloat16><<<bs * lq, th>>>(
            S, (const nv_bfloat16*)v, (nv_bfloat16*)o, bs, lq, lk, dim);
    }

    cudaDeviceSynchronize();
    cudaFree(S);
}
'''

_ext = None

def _get_ext():
    global _ext
    if _ext is None:
        _ext = load_inline(
            name="kt_attn_cublaslt_final",
            cpp_sources=_CPP,
            cuda_sources=_CUDA,
            functions=["run_attn_v4"],
            extra_cuda_cflags=["-O3", "-std=c++17", "--use_fast_math"],
            extra_ldflags=["-lcublasLt", "-lcublas"],
            verbose=False,
        )
    return _ext

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, Q, K, V):
        dim = Q.shape[-1]
        lq = Q.shape[-2]
        lk = K.shape[-2]
        bs = Q.numel() // (lq * dim)

        Qc = Q.contiguous()
        Kc = K.contiguous()
        Vc = V.contiguous()
        O = torch.empty_like(Qc)

        if Q.dtype == torch.bfloat16:
            dt = 0
        elif Q.dtype == torch.float32:
            dt = 1
        else:
            dt = 2

        _get_ext().run_attn_v4(
            Qc.data_ptr(), Kc.data_ptr(), Vc.data_ptr(), O.data_ptr(),
            bs, lq, lk, dim, dt
        )
        return O
